/**
 * Evaluation form CRUD actions.
 * @module     local_sentientia_evaluation/evaluation_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_sentientia_evaluation/evaluation_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var STATUS = {DRAFT: 0, ACTIVE: 1, ARCHIVED: 2};

    var openEvalForm = function(evaluationid, returnFocus) {
        var titleKey = (evaluationid === 0) ? "addevaluation" : "editevaluation";
        Str.get_string(titleKey, "local_sentientia_evaluation").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_sentientia_evaluation\\form\\edit_evaluation",
                args: {evaluationid: evaluationid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmStatus = function(evaluationid, name, newStatus, msgKey, returnFocus) {
        var titleKey = msgKey === "confirmpublish" ? "publishevaluation"
                     : msgKey === "confirmarchive" ? "archiveevaluation"
                     : "draftevaluation";
        Promise.all([
            Str.get_string(titleKey, "local_sentientia_evaluation"),
            Str.get_string(msgKey, "local_sentientia_evaluation", name),
            Str.get_string("evaluationstatuschanged", "local_sentientia_evaluation")
        ]).then(function(strings) {
            Notification.confirm(strings[0], strings[1], strings[0], null, function() {
                Ajax.call([{methodname: "local_sentientia_evaluation_change_status",
                            args: {evaluationid: evaluationid, status: newStatus}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[2], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
            });
            if (returnFocus) setTimeout(function() { returnFocus.focus(); }, 100);
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(evaluationid, name, returnFocus) {
        Promise.all([
            Str.get_string("deleteevaluation", "local_sentientia_evaluation"),
            Str.get_string("confirmdelete", "local_sentientia_evaluation", name),
            Str.get_string("delete", "core"),
            Str.get_string("evaluationdeleted", "local_sentientia_evaluation")
        ]).then(function(strings) {
            Notification.deleteCancelPromise(strings[0], strings[1], strings[2], returnFocus).then(function() {
                Ajax.call([{methodname: "local_sentientia_evaluation_delete_evaluation",
                            args: {evaluationid: evaluationid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[3], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var evaluationid = parseInt(trigger.dataset.evaluationid || "0", 10);
        var name = trigger.dataset.name || "this evaluation";
        switch (action) {
            case "create-evaluation":  event.preventDefault(); openEvalForm(0, trigger); break;
            case "edit-evaluation":    event.preventDefault(); openEvalForm(evaluationid, trigger); break;
            case "publish-evaluation": event.preventDefault(); confirmStatus(evaluationid, name, STATUS.ACTIVE, "confirmpublish", trigger); break;
            case "archive-evaluation": event.preventDefault(); confirmStatus(evaluationid, name, STATUS.ARCHIVED, "confirmarchive", trigger); break;
            case "draft-evaluation":   event.preventDefault(); confirmStatus(evaluationid, name, STATUS.DRAFT, "confirmdraft", trigger); break;
            case "delete-evaluation":  event.preventDefault(); confirmDelete(evaluationid, name, trigger); break;
        }
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-evaluation"]') || document.body;
            if (root.dataset.airpayEvaluationInit === "1") return;
            root.dataset.airpayEvaluationInit = "1";
            root.addEventListener("click", handleClick);
        }
    };
});
